import java.io.*
import java.util.*

const val MOD = 1_000_000_007L

fun power(b: Long, e: Long, m: Long): Long {
    var res = 1L
    var base = b % m
    var exp = e
    while (exp > 0) {
        if (exp and 1L == 1L) res = res * base % m
        base = base * base % m
        exp = exp shr 1
    }
    return res
}

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    var x = st.nextToken().toLong()
    val n = st.nextToken().toLong()
    val primes = ArrayList<Long>()
    var d = 2L
    while (d * d <= x) {
        if (x % d == 0L) {
            primes.add(d)
            while (x % d == 0L) x /= d
        }
        d++
    }
    if (x > 1) primes.add(x)
    var ans = 1L
    for (p in primes) {
        var e = 0L
        var m = n
        while (m > 0) {
            m /= p
            e += m
        }
        ans = ans * power(p % MOD, e, MOD) % MOD
    }
    println(ans)
}
